import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            n = int(n_str)
        except StopIteration:
            break

        res = [0] * n
        i = 0
        while i < n:
            if i == n - 1:
                j = i - 1
                if res[j] == 0:
                    res[j] = i + 2
                    res[i] = i + 1
                else:
                    res[i] = res[j]
                    res[j] = i + 1
                i += 1
            else:
                if res[i] == 0:
                    res[i] = i + 2
                    res[i + 1] = i + 1
                i += 2

        results.append(" ".join(map(str, res)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
